{
 "summary": "The Lean theorem proves three facts about the specific regular tetrahedron K = {(x,y,√2 t) : 0≤t≤1, |x|≤1−t, |y|≤t}. First, the infimum of its orthogonal shadow areas equals √2. Second, there exist δ>0 and C>0 such that for every 0<ε<δ there is a covering of K by exactly 2⌈2/ε²⌉ cylinders with nondegenerate triangular perpendicular bases, whose total area satisfies |Σ|B_i|/√2 − (1/2 − 13ε²/6000)| ≤ Cε⁴ and is strictly less than A_min/2. Third, some finite such covering of K has Σ|B_i|/|π_{u_i⊥}K| < 1/2. The main caveat is that Corollary 1.2 (every nondegenerate tetrahedron) is formalized only for this one regular tetrahedron, and Theorem 1.1's explicit range ε ≤ 1/2000 and constant 2 are replaced by existential δ and C.",
 "glossary": [
  {"decl": "K", "line": 17, "plain": "The tetrahedron (1.4): {(x,y,Ht) : 0≤t≤1, |x|≤1−t, |y|≤t} with H=√2.", "standard_concept": "regular tetrahedron of edge 2", "matches_standard": "yes", "note": ""},
  {"decl": "projection", "line": 20, "plain": "z ↦ z − ⟨u,z⟩u, the orthogonal projection onto u⊥ when |u|=1.", "standard_concept": "orthogonal projection π_{u⊥}", "matches_standard": "yes", "note": "Only used with unit u."},
  {"decl": "area", "line": 22, "plain": "toReal of the 2-dimensional Euclidean Hausdorff measure of a set in ℝ³.", "standard_concept": "planar Lebesgue area", "matches_standard": "unclear", "note": "This matches area only if Mathlib's euclideanHausdorffMeasure is normalized to agree with Lebesgue measure on planes. The conjunct A_min = √2 pins the normalization, so an unnormalized measure would make the theorem unprovable rather than vacuous."},
  {"decl": "shadowArea", "line": 24, "plain": "|π_{u⊥} K|", "standard_concept": "projection area A(u)", "matches_standard": "yes", "note": ""},
  {"decl": "A_min", "line": 26, "plain": "inf over unit u of |π_{u⊥}K|", "standard_concept": "A_min(K) = min over 2-planes E of |π_E K|", "matches_standard": "yes", "note": "Lean uses an infimum and does not assert that the minimum is attained. The set is nonempty and bounded below by 0, so sInf is genuine."},
  {"decl": "TriCylinder", "line": 28, "plain": "A unit axis u and a nondegenerate triangle B (convex hull of 3 affinely independent points) contained in u⊥. The compact, convex, measurable and finite-area fields are redundant consequences.", "standard_concept": "cylinder with compact triangular perpendicular base", "matches_standard": "yes", "note": ""},
  {"decl": "TriCylinder.carrier", "line": 40, "plain": "B + ℝu", "standard_concept": "cylinder", "matches_standard": "yes", "note": ""},
  {"decl": "Covers", "line": 43, "plain": "K ⊆ ⋃_i (B_i + ℝu_i)", "standard_concept": "finite cylinder covering", "matches_standard": "yes", "note": ""},
  {"decl": "relativeCost", "line": 49, "plain": "Σ |B_i| / |π_{u_i⊥} K|", "standard_concept": "directionwise normalized cost", "matches_standard": "yes", "note": "Defined only for K, not for a general tetrahedron T."},
  {"decl": "n", "line": 52, "plain": "⌈2/ε²⌉", "standard_concept": "n in (2.1)", "matches_standard": "yes", "note": ""},
  {"decl": "MainAsymptotic", "line": 54, "plain": "There exist δ,C>0 such that for all 0<ε<δ there is a covering by 2n(ε) triangular cylinders with |total/H − (1/2 − 13ε²/6000)| ≤ Cε⁴ and total < A_min/2.", "standard_concept": "Theorem 1.1 asymptotic part", "matches_standard": "partly", "note": "δ and C are existential, whereas the paper gives ε ≤ 1/2000 and C = 2."},
  {"decl": "NormalizedCounterexample", "line": 62, "plain": "Some finite triangular-cylinder covering of K has relative cost < 1/2.", "standard_concept": "Corollary 1.2", "matches_standard": "partly", "note": "Covers only K, not every nondegenerate tetrahedron."}
 ],
 "lean_claims": [
  {"theorem": "OAI.TriangularCovering.main", "line": 65, "plain": "(i) inf_{|u|=1} |π_{u⊥}K| = √2. (ii) There exist δ>0 and C>0 such that for every ε with 0<ε<δ there are 2⌈2/ε²⌉ cylinders with unit axes and nondegenerate triangular bases in u_i⊥ covering K, with |Σ|B_i|/√2 − (1/2 − 13ε²/6000)| ≤ Cε⁴ and Σ|B_i| < A_min/2. (iii) There is a finite covering of K by such cylinders with Σ|B_i|/|π_{u_i⊥}K| < 1/2."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "A_min(K)=√2. For every 0<ε≤1/2000 there is a covering by m=2⌈2/ε²⌉ cylinders with compact triangular perpendicular bases such that (1/√2)Σ|B_i| = 1/2 − 13ε²/6000 + R with |R| ≤ 2ε⁴, and Σ|B_i| < A_min(K)/2."},
  {"ref": "Lemma 2.1", "plain": "A_min(K) = H, with equality attained at u=(1,0,0)."},
  {"ref": "Corollary 1.2", "plain": "Every nondegenerate tetrahedron T admits a finite cylinder covering with compact triangular perpendicular bases with Σ|B_i|/|π_{u_i⊥}T| < 1/2."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "OAI.TriangularCovering.main", "relation": "lean_weaker", "why": "The range of ε (any δ instead of 1/2000) and the constant (any C instead of 2) are existential; the cylinder count, leading terms and strict saving match."},
  {"paper_ref": "Lemma 2.1", "lean_theorem": "OAI.TriangularCovering.main", "relation": "lean_weaker", "why": "Lean states the infimum value only, not that it is attained."},
  {"paper_ref": "Corollary 1.2", "lean_theorem": "OAI.TriangularCovering.main", "relation": "lean_weaker", "why": "Lean covers only the specific regular tetrahedron K; the affine-invariance extension to all tetrahedra is not formalized."}
 ],
 "flags": [
  {"id": "F1", "category": "coverage", "severity": "medium", "decl": "NormalizedCounterexample", "line": 62, "paper_ref": "Corollary 1.2", "explanation": "The corollary claims the counterexample for every nondegenerate tetrahedron. Lean proves it only for K, where it follows directly from part (ii) and A_min = H. The affine-invariance step is not formalized.", "polarity": "lean weaker", "probe_idea": "State ∀ v : Fin 4 → Space, AffineIndependent ℝ v → ∃ m (c : Fin m → TriCylinder), (convexHull ℝ (range v)) ⊆ ⋃ i, (c i).carrier ∧ Σ i, area (c i).base / area (projection (c i).axis '' convexHull ℝ (range v)) < 1/2."},
  {"id": "F2", "category": "quantifier", "severity": "medium", "decl": "MainAsymptotic", "line": 55, "paper_ref": "Theorem 1.1", "explanation": "The paper asserts the construction for every 0<ε≤1/2000 with remainder at most 2ε⁴. Lean only asserts existence of some δ>0 and C>0, so the explicit range and constant are lost.", "polarity": "lean weaker", "probe_idea": "Replace ∃ δ C with δ = 1/2000 (using ε ≤ δ) and C = 2."},
  {"id": "F3", "category": "definition-mismatch", "severity": "low", "decl": "area", "line": 22, "paper_ref": "Theorem 1.1", "explanation": "Area uses Measure.euclideanHausdorffMeasure 2. This equals planar Lebesgue area only if that measure is normalized. Since A_min = √2 is proved, an unnormalized measure would have made the theorem false, so this is likely fine but worth confirming.", "polarity": "unclear", "probe_idea": "Prove area of the unit square {(x,y,0) : x,y ∈ [0,1]} equals 1."},
  {"id": "F4", "category": "other", "severity": "low", "decl": "A_min", "line": 26, "paper_ref": "Lemma 2.1", "explanation": "A_min is an infimum; attainment of the minimum (the paper's 'min', equality at u=(1,0,0)) is not asserted.", "polarity": "lean weaker", "probe_idea": "Prove shadowArea !₂[1,0,0] = H."}
 ],
 "lint_verdicts": [
  {"line": 26, "rule": "junk-sInf", "verdict": "harmless", "why": "The set is nonempty (unit vectors exist) and bounded below by 0 because areas are toReal values, so sInf is the true infimum."},
  {"line": 50, "rule": "junk-div", "verdict": "harmless", "why": "Axes are unit vectors, so shadowArea ≥ A_min = √2 > 0 by part (i); the denominator is never zero."},
  {"line": 52, "rule": "junk-div", "verdict": "harmless", "why": "n is only used with ε > 0."},
  {"line": 52, "rule": "toNat-trunc", "verdict": "harmless", "why": "2/ε² > 0, so the ceiling into ℕ matches ⌈2/ε²⌉."},
  {"line": 59, "rule": "junk-div", "verdict": "harmless", "why": "H = √2 ≠ 0 and the literals are real."},
  {"line": 60, "rule": "junk-div", "verdict": "harmless", "why": "This is division by 2 in ℝ."},
  {"line": 63, "rule": "junk-div", "verdict": "harmless", "why": "1/2 is elaborated in ℝ as 0.5."}
 ]
}
